  title: {
    text: 'What moved revenue, quarter by quarter',
    align: 'left',
  },
  subtitle: {
    text: 'Currency labels are wider than the quarters they sit on. dataLabels.avoidOverlap spaces them apart.',
    align: 'left',
  },
  colors: ['#26a69a', '#ef5350', '#42a5f5'],
  dataLabels: {
    style: {
      fontSize: '11px',
    },
    formatter: function (val) {
      var abs = Math.abs(val)
      var sign = val < 0 ? '-' : '+'
      if (abs >= 1000000000)
        return sign + '$' + (abs / 1000000000).toFixed(2) + 'B'
      return sign + '$' + (abs / 1000000).toFixed(1) + 'M'
    },
  },
  xaxis: {
    labels: {
      rotate: -45,
      rotateAlways: true,
    },
  },
  yaxis: {
    labels: {
      formatter: function (val) {
        return '$' + (val / 1000000000).toFixed(1) + 'B'
      },
    },
  },
  tooltip: {
    y: {
      formatter: function (val) {
        return (val > 0 ? '+' : '') + '$' + val.toLocaleString('en-US')
      },
    },
  },
}

var chart = new ApexCharts(document.querySelector('#chart'), options)
